begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok((select relrowsecurity from pg_class where oid='public.vocabulary_photo_guidance'::regclass),'Guidance has RLS');
select ok(not has_table_privilege('anon','public.vocabulary_photo_guidance','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'Anon has no guidance table rights');
select ok(has_table_privilege('authenticated','public.vocabulary_photo_guidance','SELECT'),'Authenticated can read eligible guidance');
select ok(not has_table_privilege('authenticated','public.vocabulary_photo_guidance','INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'Authenticated cannot mutate guidance');
select ok(has_table_privilege('service_role','public.vocabulary_photo_guidance',privilege), 'Service explicit '||privilege) from unnest(array['SELECT','INSERT','UPDATE','DELETE']) privilege;
select ok(not has_table_privilege('service_role','public.vocabulary_photo_guidance','TRUNCATE,REFERENCES,TRIGGER'),'Service receives only CRUD');
select ok(not has_function_privilege(role,'private.concept_photo_guidance(uuid,text)','EXECUTE'),'Private helper denies '||role) from unnest(array['anon','authenticated','service_role']) role;
select ok(not has_column_privilege('authenticated','public.vocabulary_photo_guidance','primary_idea','UPDATE'),'No inherited client column write');
insert into auth.users(id,email) values('78000000-0000-4000-8000-000000000001','guidance_fixture@example.test'),('78000000-0000-4000-8000-000000000002','guidance_other@example.test');
select set_config('request.jwt.claim.sub','78000000-0000-4000-8000-000000000001',true);
select public.complete_onboarding('guidance_fixture','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002','A1','UTC');
create temporary table guidance_challenge as select public.get_or_create_today_challenge() payload;
create temporary table guidance_target as select (payload->'words'->0->>'concept_id')::uuid id from guidance_challenge;
select ok((select bool_and(w->'photo_guidance'='null'::jsonb) from guidance_challenge,jsonb_array_elements(payload->'words') w),'Legacy concepts require no backfill');
insert into public.vocabulary_photo_guidance(concept_id,locale,primary_idea,representation_mode,accessibility_guidance,safety_guidance)
select id,'en','Show it close up.','literal','Use a reachable position.','Keep private details outside the frame.' from guidance_target;
select is(private.concept_photo_guidance((select id from guidance_target),'fr')->>'locale','en','Missing French falls back to a whole English row');
insert into public.vocabulary_photo_guidance(concept_id,locale,primary_idea,representation_mode,accessibility_guidance,safety_guidance)
select id,'fr','Cadrez cet objet.','literal','Restez dans une position confortable.','Masquez les informations personnelles.' from guidance_target;
select is(private.concept_photo_guidance((select id from guidance_target),'fr')->>'primary_idea','Cadrez cet objet.','French retrieval prefers French');
select is(private.concept_photo_guidance((select id from guidance_target),'en')->>'primary_idea','Show it close up.','English UI receives English, independent of learning language');
select is(public.get_or_create_today_challenge()->'words'->0->'photo_guidance'->>'safety_guidance','Keep private details outside the frame.','Existing challenge RPC carries full guidance');
select is((select jsonb_agg(w-'photo_guidance' order by n) from jsonb_array_elements(public.get_or_create_today_challenge()->'words') with ordinality x(w,n)),(select jsonb_agg(w-'photo_guidance' order by n) from guidance_challenge,jsonb_array_elements(payload->'words') with ordinality x(w,n)),'Adding help preserves assignments and submission snapshots');
select throws_ok($$update public.vocabulary_photo_guidance set primary_idea=''$$,'23514',null,'Blank idea rejected');
select throws_ok($$update public.vocabulary_photo_guidance set primary_idea=repeat('x',2001)$$,'23514',null,'Oversize idea rejected');
select throws_ok($$update public.vocabulary_photo_guidance set primary_idea='x'||repeat(' ',2000)$$,'23514',null,'Whitespace cannot evade the text size limit');
select throws_ok($$update public.vocabulary_photo_guidance set safety_guidance='   '$$,'23514',null,'Blank safety rejected');
select throws_ok($$update public.vocabulary_photo_guidance set accessibility_guidance=''$$,'23514',null,'Blank access guidance rejected');
select throws_ok($$update public.vocabulary_photo_guidance set locale='es'$$,'23514',null,'Unsupported locale rejected');
select throws_ok($$update public.vocabulary_photo_guidance set representation_mode='unknown'$$,'23514',null,'Unknown mode rejected');
select throws_ok($$update public.vocabulary_photo_guidance set alternative_idea='A model'$$,'23514',null,'Alternative requires its own mode');
select throws_ok($$update public.vocabulary_photo_guidance set alternative_mode='interpretive'$$,'23514',null,'Alternative mode requires an idea');
select throws_ok($$insert into public.vocabulary_photo_guidance select * from public.vocabulary_photo_guidance$$,'23505',null,'One row per concept/locale');
select throws_ok($$update public.vocabulary_photo_guidance set concept_id='78000000-0000-4000-8000-000000000099'$$,'23503',null,'Unknown concept rejected');
set local role authenticated;
select is((select count(*) from public.vocabulary_photo_guidance),2::bigint,'Authenticated reads localized eligible rows');
select is(public.get_or_create_today_challenge()->'words'->0->'photo_guidance'->>'primary_idea','Show it close up.','Authenticated owner retrieves help through existing public RPC');
select throws_ok($$update public.vocabulary_photo_guidance set primary_idea='Hijack'$$,'42501',null,'Client writes denied');
select throws_ok($$select private.concept_photo_guidance(null,'en')$$,'42501',null,'Client helper invocation denied');
reset role;
update public.vocabulary_concepts set is_active=false where id=(select id from guidance_target);
select is(private.concept_photo_guidance((select id from guidance_target),'en'),null::jsonb,'Inactive concept has no guidance projection');
set local role authenticated;
select is((select count(*) from public.vocabulary_photo_guidance),0::bigint,'RLS hides inactive guidance');
reset role;
update public.vocabulary_concepts set is_active=true,is_photographable=false where id=(select id from guidance_target);
set local role authenticated;
select is((select count(*) from public.vocabulary_photo_guidance),0::bigint,'RLS hides ineligible non-photographable guidance');
reset role;
update public.vocabulary_concepts set is_photographable=true where id=(select id from guidance_target);
select set_config('request.jwt.claim.sub','',true);
set local role authenticated;
select is((select count(*) from public.vocabulary_photo_guidance),0::bigint,'An authenticated role without a user cannot read guidance');
reset role;
select set_config('request.jwt.claim.sub','78000000-0000-4000-8000-000000000002',true);
select is(private.challenge_payload((select (payload->'challenge'->>'id')::uuid from guidance_challenge)),null::jsonb,'Other users cannot read challenge payload/guidance');
set local role anon;
select throws_ok($$select * from public.vocabulary_photo_guidance$$,'42501',null,'Anon raw reads denied');
reset role;
delete from public.vocabulary_photo_guidance where locale='en';
select is(private.concept_photo_guidance((select id from guidance_target),'en'),null::jsonb,'English never silently displays French-only guidance');
select * from finish();
rollback;
